if dir_path is None:
    return Dir()

if isinstance(dir_path, Dir):
    return Dir(path=str(dir_path.path), url=str(dir_path.url))

if isinstance(dir_path, str):
    if dir_path.startswith("s3://"):
        parsed_url = parse.urlparse(dir_path)
        bucket = parsed_url.netloc
        object_key = parsed_url.path.strip("/")
        return Dir(path=object_key, url=f"s3://{bucket}/{object_key}")
    elif dir_path.startswith("local:"):
        resolved_path = Path(dir_path).resolve()
        return Dir(path=str(resolved_path))
    else:
        # Handle other paths (e.g., project paths)
